"""Build monochrome clock digits from the bundled OFL typeface. Requires Pillow."""

from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

root = Path(__file__).resolve().parents[1]
source = root / "assets/fonts/霞鹜臻楷.ttf"
glyphs = "0123456789:.-"
with (root / "src/generated/clock_font.inc").open("w", encoding="utf-8") as out:
    out.write(
        "// Generated by scripts/clock_font.py. Font and license: licenses/霞鹜臻楷-OFL.txt.\n"
    )
    for name, size in (("time", 83), ("reading", 33)):
        font = ImageFont.truetype(str(source), size)
        data, metrics = bytearray(), []
        for glyph in glyphs:
            left, top, right, bottom = font.getbbox(glyph, anchor="ls")
            tile = Image.new("L", (right - left, bottom - top))
            ImageDraw.Draw(tile).text(
                (-left, -top), glyph, font=font, anchor="ls", fill=255
            )
            bitmap = tile.point(lambda value: 255 if value >= 112 else 0, mode="1")
            box = bitmap.getbbox()
            assert box
            ink = bitmap.crop(box)
            metrics.append(
                (
                    len(data),
                    left + box[0],
                    top + box[1],
                    *ink.size,
                    round(font.getlength(glyph)),
                )
            )
            data.extend(ink.tobytes())
        out.write(f"static constexpr NumericGlyph {name}Glyphs[] = {{\n")
        for cells in metrics:
            out.write("  {" + ", ".join(map(str, cells)) + "},\n")
        out.write("};\n")
        out.write(f"static constexpr uint8_t {name}Pixels[] = {{\n")
        for start in range(0, len(data), 16):
            out.write(
                "  " + ", ".join(f"0x{b:02x}" for b in data[start : start + 16]) + ",\n"
            )
        out.write("};\n")
